1	import { isNavigable, type Dock, type ShipTuning } from "@pirate-sea-race/content";
2	import type { SimulationConfig } from "./config.js";
3	import { divTrunc } from "./fixed.js";
4	import { HEADING_DX, HEADING_DY, HEADING_SCALE, normalizeHeading } from "./heading.js";
5	import { AXIS_SCALE, INTERACT_BUTTON, sanitizeInput, type PlayerInput } from "./input.js";
6	import { NOT_DOCKED, tileCentre, WORLD_STEP_INTERVAL, type MatchState, type ShipState } from "./state.js";
7	
8	/**
9	 * Held inputs by ship id. A ship without an entry sails as neutral input, except that a moored ship keeps the throttle
10	 * it moored with (`mooredThrottle`): a missing entry is no input at all (the server leaves it out when a player's input
11	 * lapsed), so it cannot release that throttle, and the player's unchanged held keys do not cast off when they resume.
12	 */
13	export type StepInputs = Readonly<Record<string, PlayerInput>>;
14	
15	export function isWorldStep(frame: number): boolean {
16	  return frame % WORLD_STEP_INTERVAL === 0;
17	}
18	
19	/**
20	 * Advances the match clock by one 60 Hz step and returns the new state. World logic (sailing) runs only when the new
21	 * frame is a multiple of WORLD_STEP_INTERVAL. The input state is never mutated.
22	 */
23	export function step(config: SimulationConfig, state: MatchState, inputs: StepInputs): MatchState {
24	  const frame = state.frame + 1;
25	  if (!isWorldStep(frame)) return { ...state, frame };
26	  return {
27	    ...state,
28	    frame,
29	    worldTick: state.worldTick + 1,
30	    ships: state.ships.map((ship) => {
31	      const input = inputs[ship.id];
32	      return input === undefined && ship.dock !== NOT_DOCKED ? ship : sail(config, ship, sanitizeInput(input));
33	    }),
34	  };
35	}
36	
37	/**
38	 * One world step of one ship (§3). The throttle (`-moveY`) accelerates, brakes or reverses; `moveX` turns the
39	 * heading; the ship then moves along its heading and stops or slides against land, shoals and the map edge.
40	 *
41	 * Docking: interact near a dock moors the ship there (at the dock tile's centre, speed 0) at any speed, when its hull
42	 * is on or beside the berth tile or could sail straight there from within reach (`dockInReach`). Neither speed nor
43	 * throttle matters, so a ship driven at its dock with ahead and interact held moors on the first step it starts beside
44	 * the berth or within reach, from any angle. A moored ship stays put while interact is held,
45	 * without throttle, or while the throttle it moored with is still held; releasing that throttle and then any throttle
46	 * (or the other direction) casts off and sails in the same step.
47	 */
48	export function sail(config: SimulationConfig, ship: ShipState, input: PlayerInput): ShipState {
49	  const tuning = config.ship;
50	  const throttle = -input.moveY;
51	  const interact = (input.buttons & INTERACT_BUTTON) !== 0;
52	  const direction = Math.sign(throttle);
53	  let dock = ship.dock;
54	  if (dock !== NOT_DOCKED) {
55	    if (direction === 0 || interact || direction === ship.mooredThrottle) {
56	      const mooredThrottle = direction === 0 ? 0 : ship.mooredThrottle;
57	      return ship.speed === 0 && ship.mooredThrottle === mooredThrottle ? ship : { ...ship, speed: 0, mooredThrottle };
58	    }
59	    dock = NOT_DOCKED;
60	  } else if (interact) {
61	    const berth = dockInReach(config, ship.x, ship.y);
62	    if (berth !== undefined) {
63	      return { ...ship, ...tileCentre(config, berth.tileX, berth.tileY), speed: 0, dock: berth.id, mooredThrottle: direction };
64	    }
65	  }
66	
67	  const heading = normalizeHeading(ship.heading + Math.sign(input.moveX) * tuning.turnRate);
68	  const speed = nextSpeed(tuning, ship.speed, throttle);
69	  const dx = divTrunc(speed * HEADING_DX[heading]!, HEADING_SCALE);
70	  const dy = divTrunc(speed * HEADING_DY[heading]!, HEADING_SCALE);
71	  const x = sweepX(config, ship.x, ship.y, dx);
72	  const y = sweepY(config, x, ship.y, dy);
73	  // Blocked on every axis it tried to move along: the ship has run aground and stops. Blocked on one axis only, it
74	  // slides along the obstacle on the other.
75	  const aground = (dx !== 0 || dy !== 0) && x === ship.x && y === ship.y;
76	  return { ...ship, x, y, heading, speed: aground ? 0 : speed, dock, mooredThrottle: 0 };
