856	  /** §12 expiry: the dock the encounter rules would respawn this player at, from where their ship is (or waits). */
857	  private respawnDockOf(id: string): { x: number; y: number } {
858	    const ship = this.simulation.ships.find((each) => each.id === id);
859	    const respawn = this.encounters.players.find((each) => each.id === id)?.respawn ?? null;
860	    const from = respawn !== null ? { x: respawn.x, y: respawn.y } : ship !== undefined ? { x: ship.x, y: ship.y } : dockCentre(this.config.map, 0);
861	    const waiting = new Set(this.encounters.players.filter((each) => each.respawn !== null).map((each) => each.id));
862	    const opponents = this.simulation.ships.filter((each) => each.id !== id && !waiting.has(each.id)).map((each) => ({ x: each.x, y: each.y }));
863	    const point = this.encounterConfig.modes.ship.rules.respawnPoint({ encounter: from, own: from, opponents, clearRadius: this.encounterConfig.respawnClearRadius });
864	    return { x: point.x, y: point.y };
865	  }
