894	  /**
895	   * One world tick of §6 (`stepEncounters`): this tick's snapshot of every ship, the reports of duels that ended since
896	   * the last tick and of duels the ledger has settled, then the events applied. The rules alone choose targets, land
897	   * or miss grapples, start fights and decide returns; the room moves ships and runs the duels.
898	   */
899	  private stepEncounters(frame: number, held: ReadonlySet<string>): void {
900	    const tick = this.simulation.worldTick;
901	    const endedBy = this.protectionEndedNext;
902	    this.protectionEndedNext = new Map();
903	    const players: EncounterPlayerInput[] = this.simulation.ships.map((ship) => {
904	      const gate = this.gates.get(ship.id);
905	      const duel = this.duelOfSession(ship.id);
906	      return {
907	        id: ship.id,
908	        mode: "ship",
909	        x: ship.x,
910	        y: ship.y,
911	        heading: ship.heading,
912	        connected: this.clients.get(ship.id) !== undefined,
913	        attack: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & GRAPPLE_BUTTON) !== 0,
914	        ready: duel?.machine.isReady(ship.id) === true,
915	        // §6: last tick's collection, cache claim or treasure claim ended this player's protection.
916	        protectionEndedBy: endedBy.get(ship.id) ?? null,
917	      };
918	    });
919	    const stepped = stepEncounters(this.encounterConfig, this.encounters, { tick, players, reports: this.duelReports(tick), matchOver: false });
920	    this.encounters = stepped.state;
921	    for (const event of stepped.events) this.apply(event);
922	    this.closeShownDuels(tick);
923	  }
