925	  /** Settled duels whose result has been shown long enough leave their fighters' views. */
926	  private closeShownDuels(tick: number): void {
927	    for (const duel of [...this.seaDuels.values()]) if (duel.removeAfterTick !== undefined && tick > duel.removeAfterTick) this.closeSeaDuel(duel);
928	  }
