930	  /**
931	   * The reports for this tick. A fight that ended since the last tick is reported to the ledger (unless a player's
932	   * leaving already decided it there) and its end to the rules, as the ledger recorded it. A duel the ledger has
933	   * settled (at once for a draw, a cancellation or a win with nothing to steal; otherwise at the winner's choice or the
934	   * deadline's default) gets its `settled` report, never before: only then do its players return.
935	   */
936	  private duelReports(tick: number): DuelReport[] {
937	    const reports: DuelReport[] = [];
938	    for (const duel of this.seaDuels.values()) {
939	      const outcome = duel.machine.outcome;
940	      if (outcome !== undefined && !duel.ended) {
941	        duel.ended = true;
942	        if (findDuel(this.ledger, duel.id)?.phase === "fighting") {
943	          const winner = outcome.winner === null ? null : duel.players[outcome.winner];
944	          // §12: both fighters forfeiting on the same frame cancels; a double KO or an exact tie is a draw.
945	          const result = winner !== null ? "win" : outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw";
946	          this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: duel.id, tick, outcome: result, ...(winner !== null ? { winner } : {}) }));
947	        }
948	        if (!duel.endedByRules) reports.push(this.endReport(duel, tick));
949	      }
950	      if (!duel.ended || duel.settled) continue;
951	      const settled = findDuel(this.ledger, duel.id);
952	      if (settled === undefined || settled.phase === "settled") {
953	        duel.settled = true;
954	        const endTick = this.encounters.duels.find((each) => each.id === duel.id)?.end?.tick ?? tick;
955	        reports.push({ kind: "settled", duelId: duel.id, tick: Math.min(tick, Math.max(endTick, settled?.settlement?.tick ?? tick)) });
956	      }
957	    }
958	    return reports;
959	  }
