961	  /** The end report of a fight, as the ledger recorded its result (a quit may have decided it there first). */
962	  private endReport(duel: SeaDuel, tick: number): DuelReport {
963	    const result = findDuel(this.ledger, duel.id)?.result;
964	    if (result?.outcome === "win" && result.winner !== null) return { kind: "end", duelId: duel.id, tick, outcome: "win", winner: result.winner };
965	    if (result !== null && result !== undefined) return { kind: "end", duelId: duel.id, tick, outcome: result.outcome === "draw" ? "draw" : "cancelled" };
966	    const outcome = duel.machine.outcome!;
967	    if (outcome.winner !== null) return { kind: "end", duelId: duel.id, tick, outcome: "win", winner: duel.players[outcome.winner] };
968	    return { kind: "end", duelId: duel.id, tick, outcome: outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw" };
969	  }
