971	  private apply(event: EncounterEvent): void {
972	    switch (event.kind) {
973	      case "duel-reserved":
974	        this.ledgerStep("reserveDuel", reserveDuel(this.ledger, { duelId: event.duelId, players: event.players, tick: event.tick }));
975	        this.openSeaDuel(event.duelId, event.players, event.x, event.y, event.tick);
976	        return;
977	      case "duel-started":
978	        this.seaDuels.get(event.duelId)?.machine.start();
979	        return;
980	      case "duel-forfeited":
981	      case "duel-cancelled": {
982	        const duel = this.seaDuels.get(event.duelId);
983	        if (findDuel(this.ledger, event.duelId)?.phase === "fighting") {
984	          const report = event.kind === "duel-cancelled" ? { outcome: "cancelled" as const } : { outcome: "win" as const, winner: event.winner };
985	          this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: event.duelId, tick: event.tick, ...report }));
986	        }
987	        if (duel === undefined) return;
988	        duel.endedByRules = true;
989	        duel.ended = true;
990	        if (event.kind === "duel-cancelled") duel.machine.end(null, "cancelled");
991	        else duel.machine.end(duel.players.indexOf(event.winner) as PlayerIndex, "forfeit");
992	        return;
993	      }
994	      case "duel-settled": {
995	        const duel = this.seaDuels.get(event.duelId);
996	        if (duel === undefined) return;
997	        duel.removeAfterTick = event.tick + DUEL_RESULT_TICKS;
998	        this.state.markers.delete(duel.key);
999	        return;
1000	      }
1001	      case "player-returned":
1002	      case "player-respawned":
1003	        if (!this.simulation.ships.some((ship) => ship.id === event.playerId)) return;
1004	        this.simulation = returnShip(this.config, this.simulation, event.playerId, {
1005	          x: event.x,
1006	          y: event.y,
1007	          dock: event.kind === "player-respawned" ? (event.dockId ?? NOT_DOCKED) : NOT_DOCKED,
1008	        });
1009	        return;
1010	      case "report-refused":
1011	        this.refusedReports++;
1012	        return;
1013	      default:
1014	        // Attempts, protection and the loser's wait are mirrored from the rules' state.
1015	        return;
1016	    }
1017	  }
