1019	  /** A grapple landed: both ships stop, and their duel's countdown starts, in its lobby and marker. */
1020	  private openSeaDuel(id: string, players: readonly [string, string], x: number, y: number, tick: number): void {
1021	    // A winner who attacks again while the last result is still showing: that lobby goes now.
1022	    for (const duel of [...this.seaDuels.values()]) if (duel.players.some((player) => players.includes(player))) this.closeSeaDuel(duel);
1023	    for (const player of players) if (this.simulation.ships.some((ship) => ship.id === player)) this.simulation = stopShip(this.simulation, player);
1024	    const key = `d${this.nextDuelKey++}`;
1025	    const lobby = new SeaDuelSchema();
1026	    lobby.code = this.state.code;
1027	    lobby.practice = false;
1028	    this.state.duels.set(key, lobby);
1029	    const machine = new DuelMachine({
1030	      lobby,
1031	      seed: this.seedOf(`duel:${++this.duelsOpened}`),
1032	      // §9: each fighter's kit, the fruit they ate or the Duelist, fixed in the duel's frame-0 state.
1033	      kits: [kitOf(this.fruits, players[0]), kitOf(this.fruits, players[1])],
1034	      start: "called",
1035	      send: (sessionId, type, message) => this.clients.get(sessionId)?.send(type, message),
1036	    });
1037	    players.forEach((player, slot) => {
1038	      machine.addSeat(player, slot as PlayerIndex);
1039	      if (this.clients.get(player) === undefined) machine.drop(player);
1040	    });
1041	    // A player grappled while away counts as away from the duel from its start.
1042	    for (const player of players) {
1043	      const away = this.away.get(player);
1044	      if (away !== undefined) away.duelAbsentSince = tick;
1045	    }
1046	    machine.beginCountdown();
1047	    const marker = new DuelMarkerSchema();
1048	    marker.x = x;
1049	    marker.y = y;
1050	    marker.startTick = tick;
1051	    this.state.markers.set(key, marker);
1052	    this.seaDuels.set(id, { id, key, players, lobby, machine, endedByRules: false, ended: false, settled: false, removeAfterTick: undefined });
1053	  }
