1055	  /**
1056	   * §4 and §12's holds, one world tick: a connected player moored at a dock, out of any duel and holding E works on
1057	   * E's target there (`interactTarget`). The same target as their hold continues it; another starts a new hold from
1058	   * zero; no E, no mooring or no target cancels it (the ledger's rule: progress resets). Starting one ends protection
1059	   * on the next tick.
1060	   */
1061	  private stepChannels(frame: number, tick: number): void {
1062	    const held = this.heldPlayers();
1063	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1064	    for (const player of this.ledger.players) {
1065	      if (player.status !== "connected") continue;
1066	      const id = player.id;
1067	      const ship = ships.get(id);
1068	      const gate = this.gates.get(id);
1069	      const holding =
1070	        ship !== undefined && gate !== undefined && ship.dock !== NOT_DOCKED && !held.has(id) && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & INTERACT_BUTTON) !== 0;
1071	      const target = holding ? interactTarget(this.ledger, this.config.map, id, ship.dock) : undefined;
1072	      if (target === undefined) {
1073	        if (player.channel !== null) this.ledgerStep("cancelChannel", cancelChannel(this.ledger, { playerId: id, tick }));
1074	        continue;
1075	      }
1076	      if (sameTarget(player.channel, target)) {
1077	        const result = this.ledgerStep("progressChannel", progressChannel(this.ledger, { playerId: id, tick }));
1078	        if (result.status === "collected" || result.status === "claimed" || result.status === "failed") {
1079	          const notice = this.noticesOf(id);
1080	          notice.channelResult = result.status === "failed" ? `failed:${result.failure}` : `${result.status}:${target.type}`;
1081	          notice.channelResultAt = tick;
1082	        }
1083	        continue;
1084	      }
1085	      const started =
1086	        target.kind === "collect"
1087	          ? this.ledgerStep("startCollect", startCollect(this.ledger, { playerId: id, sourceId: target.sourceId, tick }))
1088	          : this.ledgerStep("startCacheClaim", startCacheClaim(this.ledger, { playerId: id, cacheId: target.cacheId, rubbingId: target.rubbingId, tick }));
1089	      if (started.ok && !this.protectionEndedNext.has(id)) this.protectionEndedNext.set(id, "collection");
1090	    }
1091	  }
