1093	  /**
1094	   * §9's eating, one world tick, after the encounters (so a reservation accepted on this tick interrupts it) and before
1095	   * the ledger's holds and the claim: every player in the match, at the pedestal of the dock their ship is moored at
1096	   * (unless waiting out of the world to respawn), holding F, reserved for a duel, disconnected (a drop cancels the
1097	   * channel, §12). The fruit rules alone decide who eats; each player's last result goes to their notices.
1098	   */
1099	  private stepFruits(frame: number, tick: number): void {
1100	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1101	    const waiting = new Set(this.encounters.players.filter((player) => player.respawn !== null).map((player) => player.id));
1102	    const players: FruitPlayer[] = [];
1103	    for (const player of this.ledger.players) {
1104	      if (player.status === "left") continue;
1105	      const id = player.id;
1106	      // Every player in the ledger's match has a ship and an input gate (the room's invariant).
1107	      const ship = ships.get(id)!;
1108	      const gate = this.gates.get(id)!;
1109	      players.push({
1110	        playerId: id,
1111	        pedestalId: waiting.has(id) ? null : (pedestalAtDock(this.pedestals, ship.dock)?.id ?? null),
1112	        // A lapsed input is neutral (§12), so a stalled client holds nothing.
1113	        holding: (gate.inputAt(frame).buttons & FRUIT_BUTTON) !== 0,
1114	        reserved: duelOf(this.encounters, id) !== undefined,
1115	        disconnected: player.status === "disconnected",
1116	        left: false,
1117	      });
1118	    }
1119	    const stepped = stepFruits(this.fruitConfig, this.fruits, { tick, players });
1120	    this.fruits = stepped.state;
1121	    for (const result of stepped.results) this.noteFruitResult(result);
1122	  }
1123	
1124	  /** A fruit result in its player's notices, for their panel: what ended their last attempt, or the meal. */
1125	  private noteFruitResult(result: FruitResult): void {
1126	    // Only a tick not later than the state's is rejected, and the room steps every world tick once.
1127	    if (result.kind === "tick-rejected") return;
1128	    // F still held at the pedestal the player has just emptied: the meal stays their last result, not a refusal.
1129	    if (result.kind === "eat-refused" && this.fruits.meals.some((meal) => meal.playerId === result.playerId && meal.pedestalId === result.pedestalId)) return;
1130	    const notice = this.noticesOf(result.playerId);
1131	    notice.fruitResultAt = result.tick;
1132	    if (result.kind === "eat-started") notice.fruitResult = "";
1133	    else if (result.kind === "eat-completed") notice.fruitResult = `eaten:${result.kit}`;
1134	    else notice.fruitResult = `${result.kind === "eat-refused" ? "refused" : "interrupted"}:${result.reason}`;
1135	  }
1136	
1137	  /**
1138	   * §5's claim channel, one world tick, after the encounters (so a reservation accepted on this tick resets a channel
1139	   * first) and the ledger's holds: every ship whose player is in the match, whether it holds every type (the ledger),
1140	   * holds E, is connected and protected, and every duel the encounter rules hold reserved. Returns the claim's
1141	   * `match-ended`, for the flow's step on the same tick.
1142	   */
1143	  private stepClaim(frame: number, tick: number): FlowReport | undefined {
1144	    if (this.claimConfig === undefined || this.claim === undefined) return undefined;
1145	    const held = this.heldPlayers();
1146	    const records = new Map(this.encounters.players.map((player) => [player.id, player]));
1147	    const players: ClaimPlayer[] = [];
1148	    for (const ship of this.simulation.ships) {
1149	      const player = findPlayer(this.ledger, ship.id);
1150	      if (player === undefined || player.status === "left") continue;
1151	      const gate = this.gates.get(ship.id);
1152	      players.push({
1153	        id: ship.id,
1154	        x: ship.x,
1155	        y: ship.y,
1156	        speed: ship.speed,
1157	        holdsAllTypes: holdsAllTypes(this.ledger, ship.id),
1158	        interact: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & INTERACT_BUTTON) !== 0,
1159	        connected: player.status === "connected" && this.clients.get(ship.id) !== undefined,
1160	        protected: (records.get(ship.id)?.protection ?? null) !== null,
1161	      });
1162	    }
1163	    const encounters = this.encounters.duels.map((duel) => ({ id: duel.id, playerIds: duel.players }));
1164	    const stepped = stepClaim(this.claimConfig, this.claim, { tick, players, encounters });
1165	    this.claim = stepped.state;
1166	    let end: FlowReport | undefined;
1167	    for (const event of stepped.events) end = this.applyClaimEvent(event) ?? end;
1168	    return end;
1169	  }
