1171	  private applyClaimEvent(event: ClaimEvent): FlowReport | undefined {
1172	    switch (event.kind) {
1173	      case "claim-interrupted": {
1174	        const notice = this.noticesOf(event.playerId);
1175	        notice.claimInterrupt = event.reason;
